This is a greedy simulation in event-driven time order.

**Approach.** Keep the current day `T`, each contributor's free time, and their current skill levels. Maintain a pool of unscheduled projects. Repeat the following:

1. Try each remaining project in priority order. Priority is based on score and duration. Also skip any project whose score would already be zero.
2. For a project, build a team role by role. For each role, pick the free contributor (free time ≤ T) with the lowest sufficient level, so strong contributors are saved for later and weak ones get to learn.
3. Mentoring is handled as follows. A contributor at level `need-1` qualifies if some other member holds the skill at `need` or higher. That member may be already chosen, or may be chosen later. A simple way to cover this is to process roles in descending order of required level and fill each with the best candidate. A role that needs mentoring is only accepted if a team member with the skill at the needed level already exists.
4. If a team is formed, record the project and set the members' free time to `T + D`. Apply level-ups immediately. Contributors are busy until then, so the levels are not used earlier.
5. If no project can be scheduled at `T`, advance `T` to the next completion time among busy contributors. If none are busy, stop.

**Details.**
- Skills are stored per contributor in an `unordered_map<int,int>`, with skill names mapped to ids.
- Each pass over the remaining projects costs about P × R × C if done naively, which is too slow. To bound it, for each skill I keep a list of contributors. For a role I scan only the contributors with that skill, plus level-0 candidates when mentoring applies. To keep it simple, I cap the scan: for each skill, scan the list of contributors who have it, and treat the mentored option only when they are in that list at level `need-1`. This misses the case of a contributor with no skill at all being mentored at level 1, which is a loss in quality only, not in validity.
- Event loop: at each `T`, one pass over the remaining projects, scheduling whatever fits. Then advance `T` to the next free time. The number of passes is bounded by the number of distinct completion times, and I also cap the work by a time check on the clock, stopping at about 8 seconds.
- Projects are sorted once by score/duration descending. The pass skips a project when `T + D` is at or beyond `B + S`, since it would score zero.
- Because the levels of contributors only change when a project is scheduled, and their free times were set to the completion time, the levels are applied at scheduling time. This is valid because those contributors are not reused before then.

Validity check on mentoring: the member providing the mentoring must have the skill at `need` or higher at the project's start. Their current level is up to date, since they are free at `T`. Level-ups apply after the project, so I compute the team from the pre-project levels and then update.

```cpp
#include <bits/stdc++.h>
using namespace std;
int main(){
    int C,P;
    scanf("%d %d",&C,&P);
    unordered_map<string,int> id;
    auto gid=[&](const string&s){auto it=id.find(s);if(it!=id.end())return it->second;int k=id.size();id[s]=k;return k;};
    vector<string> cn(C);
    vector<unordered_map<int,int>> lv(C);
    vector<vector<int>> bySkill;
    char buf[64];
    for(int i=0;i<C;i++){
        int n;scanf("%s %d",buf,&n);cn[i]=buf;
        for(int j=0;j<n;j++){
            int l;scanf("%s %d",buf,&l);
            int s=gid(buf);
            lv[i][s]=l;
            if((int)bySkill.size()<=s)bySkill.resize(s+1);
            bySkill[s].push_back(i);
        }
    }
    struct Pr{string name;int d,s,b;vector<pair<int,int>> r;};
    vector<Pr> pr(P);
    for(int i=0;i<P;i++){
        int r;
        scanf("%s %d %d %d %d",buf,&pr[i].d,&pr[i].s,&pr[i].b,&r);
        pr[i].name=buf;
        for(int j=0;j<r;j++){
            int l;scanf("%s %d",buf,&l);
            pr[i].r.push_back({gid(buf),l});
        }
    }
    bySkill.resize(id.size()+1);
    vector<int> ord(P);
    iota(ord.begin(),ord.end(),0);
    stable_sort(ord.begin(),ord.end(),[&](int a,int b){
        return (double)pr[a].s/pr[a].d/pr[a].r.size()>(double)pr[b].s/pr[b].d/pr[b].r.size();
    });
    vector<long long> fr(C,0);
    vector<int> done(P,0);
    vector<pair<int,vector<int>>> out;
    auto lvl=[&](int c,int s){auto it=lv[c].find(s);return it==lv[c].end()?0:it->second;};
    auto t0=clock();
    long long T=0;
    while(true){
        bool any=false;
        for(int pi:ord){
            if(done[pi])continue;
            Pr&p=pr[pi];
            if(T+p.d>=(long long)p.b+p.s)continue;
            int R=p.r.size();
            vector<int> team(R,-1);
            set<int> used;
            bool ok=true;
            vector<int> ro(R);
            iota(ro.begin(),ro.end(),0);
            sort(ro.begin(),ro.end(),[&](int a,int b){return p.r[a].second>p.r[b].second;});
            map<int,int> maxl;
            for(int k:ro){
                int s=p.r[k].first,need=p.r[k].second;
                int best=-1,bl=1000;
                for(int c:bySkill[s]){
                    if(fr[c]>T||used.count(c))continue;
                    int l=lvl(c,s);
                    bool q=l>=need||(l==need-1&&maxl.count(s)&&maxl[s]>=need);
                    if(!q)continue;
                    if(l<bl){bl=l;best=c;}
                }
                if(best<0){ok=false;break;}
                team[k]=best;used.insert(best);
                maxl[s]=max(maxl[s],lvl(best,s));
            }
            if(!ok)continue;
            for(int k=0;k<R;k++){
                int c=team[k],s=p.r[k].first;
                if(lvl(c,s)<=p.r[k].second)lv[c][s]=lvl(c,s)+1;
                fr[c]=T+p.d;
            }
            done[pi]=1;
            out.push_back({pi,team});
            any=true;
        }
        long long nt=LLONG_MAX;
        for(int c=0;c<C;c++)if(fr[c]>T)nt=min(nt,fr[c]);
        if(nt==LLONG_MAX)break;
        T=nt;
        if((double)(clock()-t0)/CLOCKS_PER_SEC>8)break;
        (void)any;
    }
    printf("%d\n",(int)out.size());
    for(auto&o:out){
        printf("%s\n",pr[o.first].name.c_str());
        for(size_t i=0;i<o.second.size();i++)printf("%s%s",i?" ":"",cn[o.second[i]].c_str());
        printf("\n");
    }
}
```

**Caveat.** The mentoring check uses the highest level among members already chosen, and roles are processed in descending requirement order. A mentee whose mentor would be picked later is therefore rejected. That is valid but conservative.
